'use strict';

function plainObject(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function buildMenu(records) {
  if (!Array.isArray(records)) throw new TypeError('Records must be an array');
  const seen = new Set();
  return records.map(record => {
    if (!plainObject(record) || typeof record.id !== 'string' ||
        typeof record.title !== 'string' || typeof record.description !== 'string') {
      throw new TypeError('Invalid record');
    }
    const key = record.id.trim();
    const label = record.title.trim();
    const detail = record.description.trim();
    if (!key || !label) throw new TypeError('Id and title must not be empty');
    if (seen.has(key)) throw new RangeError('Duplicate id');
    seen.add(key);
    return { key, label, detail, selected: false };
  });
}

function selectMenuItem(rows, key) {
  if (!Array.isArray(rows) || typeof key !== 'string' || key.trim() === '') {
    throw new TypeError('Invalid selection arguments');
  }
  return rows.map(row => {
    if (!plainObject(row) || typeof row.key !== 'string' || !row.key ||
        typeof row.label !== 'string' || typeof row.detail !== 'string' ||
        typeof row.selected !== 'boolean') {
      throw new TypeError('Invalid row');
    }
    return {
      key: row.key,
      label: row.label,
      detail: row.detail,
      selected: row.label === key
    };
  });
}

module.exports = { buildMenu, selectMenuItem };

