'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['buildMenu', 'selectMenuItem']);
const { buildMenu, selectMenuItem } = api;

const records = [
  { id: ' first ', title: ' First item ', description: ' Detail one ' },
  { id: 'second', title: 'Second item', description: '   ' }
];
const rows = buildMenu(records);
assert.deepEqual(rows, [
  { key: 'first', label: 'First item', detail: 'Detail one', selected: false },
  { key: 'second', label: 'Second item', detail: '', selected: false }
]);
assert.notStrictEqual(rows, records);
assert.notStrictEqual(rows[0], records[0]);
assert.deepEqual(records, [
  { id: ' first ', title: ' First item ', description: ' Detail one ' },
  { id: 'second', title: 'Second item', description: '   ' }
]);
const empty = buildMenu([]);
assert.deepEqual(empty, []);
assert.notStrictEqual(empty, buildMenu([]));

assert.throws(() => buildMenu([{ id: 'x', title: 'One', description: '' }, { id: ' x ', title: 'Two', description: '' }]), RangeError);
for (const invalid of [null, {}, [null], [[]], [{ id: '', title: 'Title', description: '' }], [{ id: '   ', title: 'Title', description: '' }], [{ id: 'id', title: '   ', description: '' }], [{ id: 'id', title: 3, description: '' }], [{ id: 'id', title: 'Title', description: null }]]) {
  assert.throws(() => buildMenu(invalid), TypeError);
}

const selected = selectMenuItem(rows, 'second');
assert.deepEqual(selected, [
  { key: 'first', label: 'First item', detail: 'Detail one', selected: false },
  { key: 'second', label: 'Second item', detail: '', selected: true }
]);
assert.notStrictEqual(selected, rows);
selected.forEach((row, i) => assert.notStrictEqual(row, rows[i]));
assert.equal(rows[1].selected, false);
const missing = selectMenuItem(selected, 'missing');
assert.deepEqual(missing.map(row => row.selected), [false, false]);
assert.deepEqual(selectMenuItem([], 'anything'), []);

const mutableRows = [{ key: 'a', label: 'A', detail: 'D', selected: true }];
const copy = selectMenuItem(mutableRows, 'a');
assert.deepEqual(copy, [{ key: 'a', label: 'A', detail: 'D', selected: true }]);
assert.notStrictEqual(copy[0], mutableRows[0]);
copy[0].label = 'changed';
assert.equal(mutableRows[0].label, 'A');

for (const args of [[null, 'a'], [{}, 'a'], [[null], 'a'], [[{ key: '', label: 'A', detail: '', selected: false }], 'a'], [[{ key: 'a', label: 'A', detail: '', selected: 'no' }], 'a'], [rows, ''], [rows, '   '], [rows, 1]]) {
  assert.throws(() => selectMenuItem(...args), TypeError);
}

